--
-- Table structure for table `Calificaciones`
--

CREATE TABLE `Calificaciones` (
  `id` int(11) NOT NULL,
  `inscripcion_id` int(11) NOT NULL COMMENT 'Vínculo al alumno inscrito en la clase',
  `actividad_id` int(11) NOT NULL COMMENT 'Vínculo a la actividad que se está calificando',
  `calificacion_obtenida` decimal(5,2) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

