--
-- Table structure for table `Documentos_Alumno`
--

CREATE TABLE `Documentos_Alumno` (
  `id` int(11) NOT NULL,
  `alumno_id` int(11) NOT NULL,
  `tipo_documento` varchar(50) NOT NULL,
