--
-- Table structure for table `Inscripciones`
--

CREATE TABLE `Inscripciones` (
  `id` int(11) NOT NULL,
  `alumno_id` int(11) NOT NULL COMMENT 'Referencia al ID del usuario alumno',
  `clase_id` int(11) NOT NULL COMMENT 'Referencia al ID de la clase (materia+profesor+ciclo)',
  `calificacion_final` decimal(5,2) DEFAULT NULL COMMENT 'La calificación final, se calculará después'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

